/* User-chosen local folders; no background uploads or silent filesystem access. */
(()=>{'use strict';const $=id=>document.getElementById(id);let root,backup,photos,backupFiles=[],photoFiles=[];
function status(text){for(const e of document.querySelectorAll('[data-personal-folder-status]'))e.textContent=text;}
async function stored(value){const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('KPMasterPersonalFolders',1);r.onupgradeneeded=()=>r.result.createObjectStore('handles');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});return new Promise((resolve,reject)=>{const t=db.transaction('handles',value?'readwrite':'readonly'),r=value?t.objectStore('handles').put(value,'root'):t.objectStore('handles').get('root');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);t.oncomplete=()=>db.close();});}
async function connect(){if(!window.showDirectoryPicker){status('Folder access is unavailable here. Use Download Backup, Restore File and Choose Photo instead.');return false;}root=await showDirectoryPicker({mode:'readwrite',id:'kp-master-personal-folders'});backup=await root.getDirectoryHandle('Kundali Backup',{create:true});photos=await root.getDirectoryHandle('Report Photos',{create:true});try{await stored(root);}catch(_){}await refresh();status('Folders ready in '+root.name+': Kundali Backup / Report Photos.');return true;}
async function list(handle,pattern){const result=[];if(!handle)return result;for await(const [name,item] of handle.entries())if(item.kind==='file'&&pattern.test(name))result.push({name,handle:item});return result.sort((a,b)=>a.name.localeCompare(b.name));}
async function refresh(){backupFiles=await list(backup,/\.lkp$/i);photoFiles=await list(photos,/\.(?:png|jpe?g|webp)$/i);for(const [id,files,empty]of [['personal-backup-list',backupFiles,'No backups in this folder'],['personal-photo-list',photoFiles,'No report photos in this folder']]){const select=$(id);if(select)select.replaceChildren(...(files.length?files.map((f,i)=>new Option(f.name,String(i))):[new Option(empty,'')]));}}
async function saveBackup(download=false){const chart=window.getChartData();if(download){status(await KPChartFiles.save(chart,null));return;}if(!backup&&!await connect())return;status(await KPChartFiles.save(chart,backup));await refresh();}
function validateBackup(text){const data=JSON.parse(text);if(!data||typeof data!=='object'||Array.isArray(data)||(!data.fields&&!data.basic))throw Error('This file does not contain a kundali backup.');return data;}
async function restoreFile(file){if(!file)return;if(file.size>12*1024*1024)throw Error('Choose a kundali backup smaller than 12 MB.');const data=validateBackup(await file.text());window.restoreChartData(data);status('Kundali restored: '+file.name);}
async function restoreSelected(){const item=backupFiles[Number($('personal-backup-list').value)];if(!item)throw Error('Select a backup first.');await restoreFile(await item.handle.getFile());}
async function dataImage(file){if(!file||file.size>8*1024*1024)throw Error('Choose a PNG, JPG or WebP image smaller than 8 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Cannot read this image.'));r.readAsDataURL(file);});if(!KPReportPhoto.isValid(data))throw Error('Choose a valid PNG, JPG or WebP image.');return data;}
async function choosePhoto(file){const data=await dataImage(file);KPReportPhoto.apply(data);const img=$('personal-photo-preview');if(img){img.src=data;img.hidden=false;}status('Report cover photo selected. It will be used by the existing report cover.');}
async function importPhotos(files){if(!photos&&!await connect())return;let count=0;for(const file of files){await dataImage(file);let name=file.name.replace(/[^\p{L}\p{N}._ -]/gu,'_');try{await photos.getFileHandle(name);name=Date.now()+'-'+name;}catch(_){}const target=await photos.getFileHandle(name,{create:true}),write=await target.createWritable();await write.write(file);await write.close();count++;}await refresh();status(count+' images added to Report Photos.');}
function applyFixedLogo(){const source=window.KPDefaultLogo;document.querySelectorAll('[data-personal-logo]').forEach(img=>img.src=source);let icon=document.querySelector('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.append(icon);}icon.href=source;}
function startup(){const splash=$('kp-brand-splash');const ready=()=>document.body.classList.contains('app-ready')&&window.KPHomeDashboard;let finished=false;const close=()=>{if(finished)return;finished=true;document.querySelector('.app-sidebar [data-tab="home"]')?.click();if(splash)splash.hidden=true;};$('kp-startup-continue')?.addEventListener('click',close);const start=Date.now(),check=()=>{if(ready()&&Date.now()-start>=700){close();return true;}return false;};const timer=setInterval(()=>{if(check())clearInterval(timer);},100);setTimeout(()=>{clearInterval(timer);close();},10000);}
function action(name,fn){document.querySelectorAll('[data-personal-action="'+name+'"]').forEach(button=>button.onclick=()=>Promise.resolve().then(fn).catch(e=>{if(e.name!=='AbortError')status(e.message);}));}
function init(){const host=$('settings-pane-astrologer');const panel=document.createElement('section');panel.className='personal-file-panel';panel.innerHTML='<h3>Kundali backup &amp; report photos</h3><p>Choose the extracted software folder. The app uses separate Kundali Backup and Report Photos folders. Your files stay on this device.</p><button type="button" data-personal-action="connect">Choose software folder</button><div class="personal-folder-grid"><article><h4>Kundali Backup</h4><select id="personal-backup-list" aria-label="Saved kundali backups"></select><div class="personal-actions"><button type="button" data-personal-action="backup">Save current kundali</button><button type="button" data-personal-action="restore">Restore selected</button><button type="button" data-personal-action="download">Download Backup</button><button type="button" data-personal-action="restore-file">Restore File</button></div><input id="personal-restore-input" type="file" accept=".lkp,application/json" hidden></article><article><h4>Report Photos</h4><select id="personal-photo-list" aria-label="Report photo library"></select><div class="personal-actions"><button type="button" data-personal-action="photo-selected">Use selected photo</button><button type="button" data-personal-action="photo-import">Add photos to folder</button><button type="button" data-personal-action="photo-file">Choose Photo</button><button type="button" data-personal-action="refresh">Refresh folders</button></div><input id="personal-photo-input" type="file" accept="image/png,image/jpeg,image/webp" hidden><input id="personal-photo-import" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden><img id="personal-photo-preview" alt="Selected report cover photo" hidden></article></div><p role="status" data-personal-folder-status></p>';host.append(panel);action('connect',connect);action('backup',()=>saveBackup());action('restore',restoreSelected);action('download',()=>saveBackup(true));action('restore-file',()=>$('personal-restore-input').click());action('photo-file',()=>$('personal-photo-input').click());action('photo-import',()=>$('personal-photo-import').click());action('refresh',refresh);action('photo-selected',async()=>{const item=photoFiles[Number($('personal-photo-list').value)];if(!item)throw Error('Select a report photo first.');await choosePhoto(await item.handle.getFile());});
 for(const [id,fn]of [['personal-restore-input',files=>restoreFile(files[0])],['personal-photo-input',files=>choosePhoto(files[0])],['personal-photo-import',importPhotos]])$(id).onchange=e=>{const files=[...e.target.files];if(files.length)Promise.resolve(fn(files)).catch(error=>status(error.message)).finally(()=>e.target.value='');};
 const reportButton=document.createElement('button');reportButton.type='button';reportButton.textContent='Report photo library';reportButton.className='no-print';reportButton.onclick=()=>{document.querySelector('.app-sidebar [data-tab="astrosettings"]')?.click();KPSettings.activate('astrologer');panel.scrollIntoView({block:'start'});};$('choose-report-cover-photo')?.parentElement?.append(reportButton);
 const brand=document.querySelector('.app-brand');if(brand){const img=document.createElement('img');img.className='personal-brand-icon';img.setAttribute('data-personal-logo','');img.alt='';brand.prepend(img);}applyFixedLogo();refresh().catch(()=>{});stored().then(async saved=>{if(saved&&await saved.queryPermission({mode:'readwrite'})==='granted'){root=saved;backup=await root.getDirectoryHandle('Kundali Backup');photos=await root.getDirectoryHandle('Report Photos');await refresh();status('Saved backup and photo folders connected.');}}).catch(()=>{});startup();window.KPLanguage?.localize(panel);}
window.KPPersonalWorkspace=Object.freeze({connect,refresh,saveBackup,restoreFile,validateBackup,choosePhoto});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
